    /// <summary>
    /// The arena kit's palette — the one material table in the pack with no
    /// runtime source to copy from.
    ///
    /// Every other pack material is generated by cloning the material the game
    /// already builds (see <see cref="PackMaterialGenerator"/>), because the game
    /// owns those props. The arena tiles are pack-only by design, so nothing in
    /// <c>Assets/Scripts</c> describes them and these numbers come straight from
    /// <c>build_map_props.py</c>'s MATJSON blocks — measured off the authored
    /// Principled nodes, never eyeballed. Regenerate with
    /// <c>scratchpad/gen_socdata.py</c> rather than editing by hand.
    ///
    /// The kit is a THEME AXIS: all three themes answer the same twenty slot
    /// names, which is exactly why the geometry ships once and only the palette
    /// varies. <see cref="Tokens"/> sorts longest-token-first automatically, the
    /// same defence <c>CosmeticCatalog</c> uses — <c>AssignByName</c> is a
    /// first-match substring matcher, so a hand-ordered table is a latent
    /// wrong-colour bug (<c>glow_a</c> would be swallowed by a bare <c>glow</c>,
    /// <c>team_blue</c> by <c>team</c>).
    ///
    /// Emission is the one adjusted value. The authored ratios are Cycles-scale
    /// (2.3x to 42x their own albedo); Unity's gamma LDR pipeline clips anything
    /// past 1, so these run at roughly half the authored ratio with a ceiling,
    /// and each carries its authored number in a trailing comment.
    /// </summary>
    public static class PackSocData
    {
        public struct MatDef
        {
            public string token;
            public Color baseColor;
            public float metallic;
            public float roughness;
            public float alpha;
            /// <summary>Multiple of its own albedo the surface emits; 0 = unlit.</summary>
            public float glow;
        }

        private static MatDef D(string token, float r, float g, float b,
                                float metallic, float roughness,
                                float alpha, float glow) =>
            new MatDef
            {
                token = token,
                baseColor = new Color(r, g, b, alpha),
                metallic = metallic,
                roughness = roughness,
                alpha = alpha,
                glow = glow,
            };

