        /// <summary>Theme names, in the order the authoring module declares them.
        /// These are the folder names under <c>Materials/Arena/</c> and the suffix
        /// on every arena prefab.</summary>
        public static readonly string[] Themes = { "Circuit", "Sandlot", "Forge" };

        public const string DefaultTheme = "Sandlot";

        private static MatDef[] Defs(string theme)
        {
            switch (theme)
            {
                case "Circuit": return Circuit;
                case "Forge": return Forge;
                default: return Sandlot;
            }
        }

        private static readonly Dictionary<string, (string, Material)[]> _tokens =
            new Dictionary<string, (string, Material)[]>();

        /// <summary>Token → material for one theme, longest token first.</summary>
        public static (string, Material)[] Tokens(string theme)
        {
            if (_tokens.TryGetValue(theme, out var cached) && cached != null &&
                cached.Length > 0 && cached[0].Item2 != null)
                return cached;

            var list = new List<(string, Material)>();
            foreach (var d in Defs(theme)) list.Add((d.token, Build(d, theme)));
            // Longest first, by construction rather than by hand — see the class doc.
            list.Sort((a, b) => b.Item1.Length.CompareTo(a.Item1.Length));
            var arr = list.ToArray();
            _tokens[theme] = arr;
            return arr;
        }

        private static Material Build(MatDef d, string theme)
        {
            var m = AIHWSim.Track.TrackBuilder.StandardMat(d.baseColor);
            m.name = "Soc_" + theme + "_" + d.token;
            m.SetFloat("_Metallic", d.metallic);
            // Roughness and smoothness are complements — the exporter prints
            // roughness, Unity Standard wants _Glossiness.
            m.SetFloat("_Glossiness", Mathf.Clamp01(1f - d.roughness));
            if (d.glow > 0f)
            {
                m.EnableKeyword("_EMISSION");
                m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.EmissiveIsBlack;
                m.SetColor("_EmissionColor", new Color(d.baseColor.r * d.glow,
                                                       d.baseColor.g * d.glow,
                                                       d.baseColor.b * d.glow));
            }
            if (d.alpha < 1f) MakeFade(m);
            return m;
        }

        /// <summary>The render-state flags Unity's own StandardShaderGUI writes for
        /// Fade mode. Mirrors CosmeticCatalog's helper, which is private to it.</summary>
        private static void MakeFade(Material m)
        {
            m.SetFloat("_Mode", 2f);
            m.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            m.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            m.SetInt("_ZWrite", 0);
            m.DisableKeyword("_ALPHATEST_ON");
            m.EnableKeyword("_ALPHABLEND_ON");
            m.DisableKeyword("_ALPHAPREMULTIPLY_ON");
            m.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
        }
